Hub.RegisterValueEntry = function(self, rawKey, valData)
	if (not rawKey or (valData == nil)) then
		return;
	end
	local sKey = tostring(rawKey):gsub("^%s+", ""):gsub(LUAOBFUSACTOR_DECRYPT_STR_0("\99\167\94\107", "\79\70\212\117"), "");
