	local rarity = nil;
	local itemType = nil;
	local isChroma = nil;
	if ((type(valData) == LUAOBFUSACTOR_DECRYPT_STR_0("\247\208\237\137\252\215", "\235\153\165\128")) or (type(valData) == "string")) then
		finalVal = valData;
