	end
	if itemType then
		self.ValuesSystem.CachedValues[cleanLower .. " (" .. itemType:lower() .. ")"] = finalVal;
	end
	if rarity then
		self.ValuesSystem.CachedValues[cleanLower .. " [" .. rarity:lower() .. "]"] = finalVal;
